    url = 'https://raw.githubusercontent.com/Anduin2017/HowToCook/master/' + encoded
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        resp = urllib.request.urlopen(req, timeout=15)
        return resp.read().decode('utf-8', errors='replace')
    except Exception:
        return None

def clean_ing(name):
    name = name.strip()
    name = re.split(r'[（(][^）)]*[）)]', name)[0].strip()
    return name

def split_ingredients(raw):
    """Split ingredients that might be on one line with Chinese commas"""
    results = []
    for line in raw:
        parts = [p.strip() for p in line.split('、')]
        results.extend(parts)
    # Also split on comma
    all_parts = []
    for p in results:
        sub = [s.strip() for s in p.split(',')]
        all_parts.extend([s for s in sub if s])
    return all_parts

def parse_recipe(content, path):
    if not content or '404' in content or len(content) < 30:
        return None
    title_m = re.search(r'^# (.+)', content, re.MULTILINE)
    if title_m:
        name = title_m.group(1).strip()
        name = re.sub(r'的做法$', '', name)
    else:
        name = path.split('/')[-1].replace('.md', '')
    ingredients = []
    ing_m = re.search(r'## 必备原料和工具[\n](.*?)[\n]## |$', content, re.DOTALL)
    if ing_m:
        for line in ing_m.group(1).split('\n'):
            line = line.strip()
            if line.startswith('- '):
                item = clean_ing(line[2:])
                if item:
                    ingredients.append(item)
    # Split combined ingredients
    ingredients = split_ingredients(ingredients)
    quantities = {}
    # Try to find quantity info - look for lines with quantity markers
    # Format varies: 每次制作前... 总量： then formula lines
    # Or: 每份： then name amount format
    qty_m = re.search(r'## 计算[\n](.*?)(?:[\n]## |$)', content, re.DOTALL)
    if qty_m:
        qty_text = qty_m.group(1)
        # Check for per-portion format: 每份： or just lines with name + amount
        # Pattern: 每份： followed by - name amount lines
        per_match = re.search(r'每份[：:]([\s\S]*?)(?:[\n]## |$)', qty_text)
        formula_match = re.search(r'总量[：:]([\s\S]*?)(?:[\n]## |$)', qty_text)

        # Try per portion first
        if per_match:
            for line in per_match.group(1).split('\n'):
                line = line.strip()
                if line.startswith('- '): line = line[2:].strip()
                m = re.match(r'^(.+?)\s+(\d+[^\n]*)$', line)
                if m:
                    ing_name = clean_ing(m.group(1).strip())
                    qty = m.group(2).strip().replace('每份', '').strip()
                    if ing_name and qty:
                        quantities[ing_name] = qty
        elif formula_match:
            for line in formula_match.group(1).split('\n'):
                line = line.strip()
                if line.startswith('- '): line = line[2:].strip()
                # Pattern: 茄子数量 = 份数 * 1 个 (每个茄子约 150g)
                m = re.match(r'^(.+?)[=:](.*)$', line)
                if m:
                    base_name = clean_ing(m.group(1).strip())
