                    qty_m2 = re.search(r'(\d+[^\n]+)', m.group(2).strip())
                    qty = qty_m2.group(1).strip() if qty_m2 else m.group(2).strip()
                    # Remove weight notes
                    qty = re.sub(r'（[^）]*）', '', qty).strip()
                    if base_name and qty:
                        quantities[base_name] = qty
    return {'name': name, 'ingredients': ingredients, 'quantities': quantities}

